package com.bangon.kiosk.config;
import com.bangon.kiosk.repository.CustomerRepository;import org.springframework.context.annotation.*;import org.springframework.security.authentication.*;import org.springframework.security.core.userdetails.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.web.csrf.CookieCsrfTokenRepository;import org.springframework.security.web.csrf.CsrfTokenRequestAttributeHandler;
@Configuration public class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean UserDetailsService users(CustomerRepository repo){return email->{var c=repo.findByEmailIgnoreCase(email).orElseThrow(()->new UsernameNotFoundException("Invalid login"));return User.withUsername(c.email).password(c.passwordHash).roles(c.role).build();};}
 @Bean SecurityFilterChain chain(HttpSecurity http)throws Exception{http.csrf(csrf->csrf.csrfTokenRepository(CookieCsrfTokenRepository.withHttpOnlyFalse()).csrfTokenRequestHandler(new CsrfTokenRequestAttributeHandler())).authorizeHttpRequests(a->a.requestMatchers("/api/admin/**").hasRole("ADMIN").requestMatchers("/api/customers/**","/api/auth/logout").authenticated().anyRequest().permitAll()).formLogin(f->f.disable()).httpBasic(b->b.disable()).logout(l->l.disable());return http.build();}
}
